"""The exact-HEAD Browser review must be generated by real Actions before upload."""
import hashlib
import json
from pathlib import Path
import struct
import subprocess
import sys
import tempfile
import unittest
import zlib

ROOT = Path(__file__).resolve().parents[1]
WORKFLOW = ROOT / ".github/workflows/quality.yml"
INDEX = ROOT / "bin/visual-review-index.py"
HEAD = "c" * 40


def chunk(kind, payload):
    data = kind + payload
    return struct.pack(">I", len(payload)) + data + struct.pack(">I", zlib.crc32(data) & 0xFFFFFFFF)


def png():
    width, height = 390, 900
    header = struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)
    scanline = b"\0" + b"\0" * (width * 3)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", header)
            + chunk(b"IDAT", zlib.compress(scanline * height)) + chunk(b"IEND", b""))


class BrowserReviewActions(unittest.TestCase):
    def test_workflow_gates_exact_head_index_before_upload(self):
        source = WORKFLOW.read_text(encoding="utf-8")
        require = source.index("      - name: Require complete visual evidence")
        generate = source.index("      - name: Generate exact-HEAD browser visual review")
        upload = source.index("      - name: Upload browser artifacts")
        self.assertLess(require, generate)
        self.assertLess(generate, upload)
        step = source[generate:upload]
        self.assertIn("SLATEFRAME_EVIDENCE_SHA:", step)
        self.assertIn('test "$(git rev-parse HEAD)" = "$SLATEFRAME_EVIDENCE_SHA"', step)
        self.assertIn('python3 bin/visual-review-index.py test-artifacts/screenshots "$SLATEFRAME_EVIDENCE_SHA" --output test-artifacts/browser-review.html', step)
        self.assertIn("test -s test-artifacts/browser-review.html", step)
        self.assertIn("test-artifacts/browser-review.html", source[upload:source.index("\n  package:", upload)])

    def fixture(self, directory):
        root = directory / "screenshots"
        root.mkdir()
        name = "appearance-default-390-ltr.png"
        data = png()
        (root / name).write_bytes(data)
        digest = hashlib.sha256(data).hexdigest()
        record = {"name": name, "sha256": digest, "width": 390, "height": 900}
        (root / "HEAD_SHA.txt").write_text(HEAD + "\n", encoding="ascii")
        (root / "BROWSER_SCREENSHOT_INVENTORY.json").write_text(json.dumps({
            "schema_version": 1, "head_sha": HEAD, "run_id": "123",
            "run_attempt": "1", "screenshots": {name: {**record, "bytes": len(data)}}
        }), encoding="utf-8")
        (root / "VISUAL_EVIDENCE.json").write_text(json.dumps({
            "schema_version": 1, "head_sha": HEAD, "files": [record]
        }), encoding="utf-8")
        return root, name

    def run_cli(self, root, head, output):
        return subprocess.run(
            [sys.executable, str(INDEX), str(root), head, "--output", str(output)],
            capture_output=True, text=True, check=False, timeout=15,
        )

    def test_cli_writes_real_linked_index_without_modifying_evidence(self):
        with tempfile.TemporaryDirectory() as temporary:
            directory = Path(temporary)
            root, name = self.fixture(directory)
            output = directory / "browser-review.html"
            before = hashlib.sha256((root / name).read_bytes()).hexdigest()
            result = self.run_cli(root, HEAD, output)
            self.assertEqual(result.returncode, 0, result.stderr)
            html = output.read_text(encoding="utf-8")
            self.assertIn("exact HEAD " + HEAD, html)
            self.assertIn("Required visual evidence", html)
            self.assertIn('href="screenshots/' + name + '"', html)
            self.assertNotIn("<script", html)
            self.assertEqual(hashlib.sha256((root / name).read_bytes()).hexdigest(), before)

    def test_cli_rejects_stale_head_and_unsafe_output_location(self):
        with tempfile.TemporaryDirectory() as temporary:
            directory = Path(temporary)
            root, _ = self.fixture(directory)
            output = directory / "browser-review.html"
            self.assertNotEqual(self.run_cli(root, "d" * 40, output).returncode, 0)
            self.assertFalse(output.exists())
            nested = root / "browser-review.html"
            self.assertNotEqual(self.run_cli(root, HEAD, nested).returncode, 0)
            self.assertFalse(nested.exists())

    def test_cli_rejects_linked_evidence_before_creating_index(self):
        with tempfile.TemporaryDirectory() as temporary:
            directory = Path(temporary)
            root, name = self.fixture(directory)
            original = root / name
            original.unlink()
            original.symlink_to(root / "HEAD_SHA.txt")
            output = directory / "browser-review.html"
            self.assertNotEqual(self.run_cli(root, HEAD, output).returncode, 0)
            self.assertFalse(output.exists())


if __name__ == "__main__":
    unittest.main()
